#pragma once

// map.hpp — Static level geometry for the "Dust" CSGO-inspired map.
//
// The map is represented as a flat list of axis-aligned box walls.
// No BSP or portal required at this scale. drawMap() iterates the list
// and calls drawTexturedBox() for each wall (defined in main.cpp).
//
// Coordinate system matches main.cpp (kArenaHalfSize = 80):
//   X = east/west, Z = north/south, Y = up
//
// Layout (bird's-eye, not to scale):
//
//   +--T-Spawn--+---Mid---+--A-Site--+
//   |           |         |          |
//   |  T-start  | central |  A bomb  |
//   |           |  open   |          |
//   +-----------+----+----+----------+
//                    |   B corridor
//               +----+----+
//               |  B-Site  |
//               +----------+

#include <SFML/Graphics.hpp>
#include <vector>

// Forward declarations — defined in main.cpp
struct Vec3;
void drawTexturedBox(const Vec3& center, float halfX, float halfY, float halfZ,
                     unsigned int texture, const sf::Color& tint, float tileScale);

// A single axis-aligned wall box in the level.
struct MapWall {
    Vec3   center;
    float  hx = 0.0f;   // half-extent in X
    float  hy = 0.0f;   // half-extent in Y
    float  hz = 0.0f;   // half-extent in Z
    unsigned int tex = 0;
    sf::Color    tint = sf::Color::White;
    float  tileScale  = 3.0f;
};

// Rectangular region on the XZ plane used for enemy and player spawning.
struct SpawnZone {
    float minX = 0.0f;
    float maxX = 0.0f;
    float minZ = 0.0f;
    float maxZ = 0.0f;
};

// Spawn zone constants — used by spawnEnemy() in main.cpp.
// T-spawn: player always starts here.
constexpr float kTSpawnX  = -60.0f;
constexpr float kTSpawnZ  = -60.0f;

