432	    game.layoutIndex = (wave - 1) % 3;
433	    game.enemies.clear();
434	    game.pickups.clear();
435	    game.enemiesRemainingToSpawn = enemiesForWave(wave);
436	    game.totalEnemiesThisWave = game.enemiesRemainingToSpawn;
437	    game.player.health = std::min(100.0f, game.player.health + 18.0f);
438	    game.player.rapidFireTimer = std::max(0.0f, game.player.rapidFireTimer - 1.0f);
439	    game.player.pos = Vec3{0.0f, kPlayerHeight * 0.5f, 0.0f};
