    h = (h ^ (h >> 16)) * 0x45d9f3bU;
    h = (h ^ (h >> 16)) * 0x45d9f3bU;
    h ^= (h >> 16);
    return static_cast<std::uint8_t>(h & 0xFFU);
}

// Smooth 2-octave noise in [0, 1] for a pixel.
// Bilinear-interpolates between hash samples at two scales for smooth grain.
// Octave 1: scale 8 pixels (low freq), weight 0.65
// Octave 2: scale 3 pixels (high freq), weight 0.35
inline float smoothNoise(int x, int y, int seed) {
    auto lerp = [](float a, float b, float t) { return a + (b - a) * t; };
    auto sample = [&](int scale, int s) -> float {
        const int gx = x / scale;
        const int gy = y / scale;
        const float tx = static_cast<float>(x % scale) / static_cast<float>(scale);
        const float ty = static_cast<float>(y % scale) / static_cast<float>(scale);
        const float n00 = hashNoise(gx,     gy,     s) / 255.0f;
        const float n10 = hashNoise(gx + 1, gy,     s) / 255.0f;
        const float n01 = hashNoise(gx,     gy + 1, s) / 255.0f;
        const float n11 = hashNoise(gx + 1, gy + 1, s) / 255.0f;
        return lerp(lerp(n00, n10, tx), lerp(n01, n11, tx), ty);
    };
    return sample(8, seed) * 0.65f + sample(3, seed + 1) * 0.35f;
}

