inline std::vector<MapWall> buildMapWalls(unsigned int wallTex,
                                          unsigned int concreteTex,
                                          unsigned int metalTex) {
    constexpr float kWH  = 4.0f;   // wall half-height (total 8 units)
    constexpr float kWT  = 2.0f;   // wall half-thickness
    constexpr float kFH  = 0.5f;   // floor slab half-height
    constexpr float kTS  = 3.0f;   // tile scale for walls
    constexpr float kFTS = 8.0f;   // tile scale for floor

    // Helper lambdas for common wall and floor orientations
    auto wall = [&](float cx, float cz, float hx, float hz,
                    unsigned int tex, float ts = kTS) -> MapWall {
        return { Vec3{cx, kWH, cz}, hx, kWH, hz, tex, sf::Color::White, ts };
    };
    auto floor = [&](float cx, float cz, float hx, float hz,
                     unsigned int tex, float ts = kFTS) -> MapWall {
        return { Vec3{cx, 0.0f, cz}, hx, kFH, hz, tex, sf::Color::White, ts };
    };
    auto crate = [&](float cx, float cz) -> MapWall {
        return { Vec3{cx, 2.8f, cz}, 3.0f, 2.8f, 3.0f, metalTex, sf::Color::White, 2.0f };
    };

    // (void)wallTex; not needed if we use it below
    std::vector<MapWall> walls;
    walls.reserve(50);

    // ---- FLOORS ----
    walls.push_back(floor(-50, -50, 28, 28, concreteTex));   // T-Spawn floor
    walls.push_back(floor(  0, -32, 22, 46, concreteTex));   // Mid floor
    walls.push_back(floor( 50, -46, 28, 32, concreteTex));   // A-Site floor
    walls.push_back(floor(  0,  28, 14, 14, concreteTex));   // B-Corridor floor
    walls.push_back(floor(  0,  60, 28, 18, concreteTex));   // B-Site floor

    // ---- T-SPAWN WALLS (brick) ----
    walls.push_back(wall(-50, -78, 28, kWT, wallTex));         // North
    walls.push_back(wall(-78, -50, kWT, 28, wallTex));         // West
    walls.push_back(wall(-50, -22, 28, kWT, wallTex));         // South

    // East wall — two segments with a passage at z=-50 to -30
    walls.push_back(wall(-22, -64, kWT, 14, concreteTex));     // East top
    walls.push_back(wall(-22, -26, kWT,  4, concreteTex));     // East bottom

    // ---- MID WALLS (concrete) ----
    walls.push_back(wall(  0, -78, 22, kWT, concreteTex));     // North
    walls.push_back(wall(-22, -4,  kWT, 18, concreteTex));     // West (south part)
    // East wall — passage to A-site at z=-50 to -28
    walls.push_back(wall( 22, -64, kWT, 14, concreteTex));     // East top
    walls.push_back(wall( 22, -7,  kWT, 21, concreteTex));     // East bottom
    // South — gap for B-corridor entrance (x=-14 to 14)
    walls.push_back(wall(-18,  14, 4, kWT, concreteTex));      // South-west piece
    walls.push_back(wall( 18,  14, 4, kWT, concreteTex));      // South-east piece

    // ---- A-SITE WALLS (brick) ----
    walls.push_back(wall( 50, -78, 28, kWT, wallTex));         // North
    walls.push_back(wall( 78, -46, kWT, 32, wallTex));         // East
    walls.push_back(wall( 50, -14, 28, kWT, wallTex));         // South

    // ---- B-CORRIDOR WALLS (concrete) ----
    walls.push_back(wall(-14,  28, kWT, 14, concreteTex));     // West
    walls.push_back(wall( 14,  28, kWT, 14, concreteTex));     // East
    // Shoulder walls where corridor meets B-site
    walls.push_back(wall(-21,  42, 7, kWT, concreteTex));      // NW shoulder
    walls.push_back(wall( 21,  42, 7, kWT, concreteTex));      // NE shoulder

    // ---- B-SITE WALLS (brick) ----
    walls.push_back(wall(-28,  60, kWT, 18, wallTex));         // West
    walls.push_back(wall( 28,  60, kWT, 18, wallTex));         // East
    walls.push_back(wall(  0,  78, 28, kWT, wallTex));         // South

    // ---- OUTER BORDER (prevents exit into void) ----
    walls.push_back(wall(-78,  28, kWT, 50, concreteTex));     // Far west (south of T-spawn)
    walls.push_back(wall( 78,  32, kWT, 46, concreteTex));     // Far east (south of A-site)
    walls.push_back(wall(-54,  78, 26, kWT, concreteTex));     // Far south-west
    walls.push_back(wall( 54,  78, 26, kWT, concreteTex));     // Far south-east

    // ---- COVER OBJECTS ----
    walls.push_back(crate(-44, -44));  // T-spawn cover
    walls.push_back(crate(-42, -58));  // T-spawn second crate
    walls.push_back(crate( 40, -60));  // A-site cover
    walls.push_back(crate( 58, -44));  // A-site second crate
    walls.push_back(crate( 58, -60));  // A-site third crate
    walls.push_back(crate(  0, -54));  // Mid box
    walls.push_back(crate(  0,  60));  // B-site centre crate

    return walls;
}

// Renders the ground and every wall in the map.
// Replaces drawArena(). Requires OpenGL 2.1 context + GL_TEXTURE_2D.
inline void drawMap(const std::vector<MapWall>& walls) {
    for (const auto& w : walls) {
        drawTexturedBox(w.center, w.hx, w.hy, w.hz, w.tex, w.tint, w.tileScale);
    }
}

